import type { LibrarySeed } from "@/lib/task-library-seed";

export const INTERNAL_AUDIT_LIBRARIES: LibrarySeed[] = [{"key":"IA-SID","name":"Internal Audit — Siddhartha Logistics FTWZ (SID)","scope":{"type":"client","value":"SID","legacy_code":"SID"},"areas":[{"code":"SID-A01","name":"Sales Verification","subtasks":[{"code":"SID-A01-S01","name":"Job Reports Verification","steps":[{"code":"SID-A01-S01-01","text":"Using random sampling, select high-value job reports and obtain physical copies from management for verification.","notes":"Note: Select job reports based on materiality and categorize them into: Opening Jobs Jobs Generated During the Period Jobs Closed During the Period Based on the above classification, determine the closing jobs as per records and reconcile with the software data"},{"code":"SID-A01-S01-02","text":"Ensure all reimbursable income is recorded against the corresponding reimbursable expenses.","notes":""},{"code":"SID-A01-S01-03","text":"Verify that all recorded expenses are supported by appropriate vouchers, invoices, and approval emails maintained in the respective folders/attachments.","notes":""},{"code":"SID-A01-S01-04","text":"Confirm that job reports are updated up to the reporting date to ensure accurate recognition of profit in the books of accounts.","notes":""},{"code":"SID-A01-S01-05","text":"Inquire about jobs shown as closed in the reports but remaining open in the accounting/software records, and verify the reasons for discrepancies.","notes":""}]}]},{"code":"SID-A02","name":"Purchase & Expenses Verification","subtasks":[{"code":"SID-A02-S01","name":"Purchase and Expenses Verification","steps":[{"code":"SID-A02-S01-01","text":"The Management will provide all the Physical Folders for Verification Purpose","notes":""},{"code":"SID-A02-S01-02","text":"Additionally the Management will Provide the Specified Job Reference in the Folder which need to be cross verify in the accounts book","notes":""},{"code":"SID-A02-S01-03","text":"Based on the Sampling verify the Majority of the Transaction with date, amount, Mode of Pay and Approval sign in the seal affixed","notes":""}]}]},{"code":"SID-A03","name":"Statutory Compliance Verification","subtasks":[{"code":"SID-A03-S01","name":"1. TDS (Tax Deducted at Source)","steps":[{"code":"SID-A03-S01-01","text":"Verify that TDS has been deducted at the applicable rates on eligible payments and correctly recorded in Tally.","notes":"For More Info: https://taxguru.in/income-tax/income-tax-act-2025-tds-rates-thresholds-compliance-ty-2026-27.html"},{"code":"SID-A03-S01-02","text":"Cross-check TDS deductions with challans, TDS returns, and ensure timely deposit with the government.","notes":""},{"code":"SID-A03-S01-03","text":"Check Interest Calculation if any late payement in TDS","notes":""}]},{"code":"SID-A03-S02","name":"2. PF (Provident Fund)","steps":[{"code":"SID-A03-S02-01","text":"Check that contributions are generally calculated at 12% of Basic wages + Dearness Allowance","notes":"For More Info: https://www.epfindia.gov.in/site_docs/PDFs/MiscPDFs/Employer_Information_Booklet.pdf"},{"code":"SID-A03-S02-02","text":"Verify the employee master data (joining date, basic wages, employee category, and UAN details).","notes":""},{"code":"SID-A03-S02-03","text":"Verify that the employer’s contribution is appropriately allocated between EPF, EPS, and EDLI schemes as applicable.","notes":""},{"code":"SID-A03-S02-04","text":"Verify monthly filing of PF Electronic Challan-cum-Return (ECR) through the EPFO portal.","notes":""},{"code":"SID-A03-S02-05","text":"Verify PF payable and expense ledgers in Tally for correct accounting treatment.","notes":""},{"code":"SID-A03-S02-06","text":"EPFO provisions, the statutory wage ceiling for PF contribution is ₹15,000 per month","notes":""},{"code":"SID-A03-S02-07","text":"To pay contribution on higher wages, a joint request from both employer and employee is required [Para 26(6) of EPF Scheme]. In such case employer has to pay Administrative charges in A/c.No.2 on the higher wages. (wages above Rs.15,000/-).","notes":""}]},{"code":"SID-A03-S03","name":"3. Employees’ State Insurance Corporation","steps":[{"code":"SID-A03-S03-01","text":"Verify coverage based on the applicable wage ceiling of ₹21,000 per month (₹25,000 per month for employees with disabilities).","notes":"For More Info: https://esic.gov.in/attachments/publicationfile/6f673bcd3d6110170f790d2909767b4f.pdf?utm"},{"code":"SID-A03-S03-02","text":"Employee Contribution: Verify that employee contribution is calculated at 0.75% of wages.","notes":""},{"code":"SID-A03-S03-03","text":"Employer Contribution: Verify that employer contribution is calculated at 3.25% of wages.","notes":""},{"code":"SID-A03-S03-04","text":"Reconcile ESIC deductions in the salary register with the ESIC payable ledger in Tally.","notes":""},{"code":"SID-A03-S03-05","text":"Check ESIC challans and bank payment proofs for timely remittance","notes":""},{"code":"SID-A03-S03-06","text":"Check that employer contribution is not deducted from employee salary.","notes":""}]},{"code":"SID-A03-S04","name":"4.GST Compliance Verification","steps":[{"code":"SID-A03-S04-01","text":"Verify sales invoices recorded in Tally with GST sales register and ensure invoice number, date, customer GSTIN, taxable value, and GST rate are correctly captured.","notes":""},{"code":"SID-A03-S04-02","text":"Reconcile sales turnover as per Tally with turnover reported in GSTR-1 and tax liability discharged through GSTR-3B.","notes":""},{"code":"SID-A03-S04-03","text":"Reconcile purchase register with GSTR-2B to ensure eligible Input Tax Credit is claimed only for valid invoices.","notes":""},{"code":"SID-A03-S04-04","text":"Check whether blocked credits under GST provisions are excluded from ITC claims.","notes":""},{"code":"SID-A03-S04-05","text":"Verify timely filing of: GSTR-1 (Outward supply details) GSTR-3B (Summary return and tax payment)","notes":""},{"code":"SID-A03-S04-06","text":"Perform reconciliation between: 1.Sales Register vs GSTR-1 2.GST Liability vs GSTR-3B 3.Purchase Register vs GSTR-2B 4.ITC claimed vs eligible ITC","notes":""}]}]},{"code":"SID-A04","name":"Cash and Bank Balance Verification","subtasks":[{"code":"SID-A04-S01","name":"1. Cash Balance verification","steps":[{"code":"SID-A04-S01-01","text":"Check the cash book and note the recorded cash balance as of the verification date.","notes":""},{"code":"SID-A04-S01-02","text":"Count all cash available, including: Notes (by denomination) Coins Petty cash balance (if applicable)","notes":""},{"code":"SID-A04-S01-03","text":"Match the physically counted cash with the cash book balance.","notes":""}]},{"code":"SID-A04-S02","name":"2. Bank Balance Verification","steps":[{"code":"SID-A04-S02-01","text":"Obtain the latest bank statement from the bank.","notes":""},{"code":"SID-A04-S02-02","text":"Compare the bank statement balance with the balance shown in the books of accounts.","notes":""},{"code":"SID-A04-S02-03","text":"Prepare a summary report of unreconciled items with reasons and status of resolution.","notes":""}]}]},{"code":"SID-A05","name":"Budget Vs Actuals","subtasks":[{"code":"SID-A05-S01","name":"Budget Vs Actuals","steps":[{"code":"SID-A05-S01-01","text":"Obtain the budgeted expense estimates prepared by management.","notes":""},{"code":"SID-A05-S01-02","text":"Compare the actual expenses incurred by the Company with the corresponding budgeted figures.","notes":""},{"code":"SID-A05-S01-03","text":"Identify and analyze significant variances between actual and budgeted expenses.","notes":""},{"code":"SID-A05-S01-04","text":"Obtain reasons for material variations and report significant deviations to management for review and necessary action.","notes":""}]}]},{"code":"SID-A06","name":"Fixed Asset Verification","subtasks":[{"code":"SID-A06-S01","name":"Fixed Asset Verification","steps":[{"code":"SID-A06-S01-01","text":"Obtain the fixed asset register maintained by the Company and verify the details such as asset description, location, asset identification number, purchase date, and cost.","notes":""},{"code":"SID-A06-S01-02","text":"Select fixed assets on a materiality basis and physically verify the existence and condition of the assets at the respective locations.","notes":""},{"code":"SID-A06-S01-03","text":"Reconcile the physically verified assets with the fixed asset register and identify any discrepancies, missing assets, or unrecorded assets.","notes":""},{"code":"SID-A06-S01-04","text":"Verify ownership documents, purchase invoices, and supporting records for selected high-value fixed assets.","notes":""},{"code":"SID-A06-S01-05","text":"Ensure depreciation is correctly calculated and recorded as per the Company’s accounting policies and applicable standards.","notes":""}]}]},{"code":"SID-A07","name":"Trade Receivables Ageing and Payable Ageing","subtasks":[{"code":"SID-A07-S01","name":"Trade Receivables Ageing and Payable Ageing","steps":[{"code":"SID-A07-S01-01","text":"Obtain the trade receivables and trade payables ageing reports from the Managememt Both $ and ₹","notes":""},{"code":"SID-A07-S01-02","text":"Analyze outstanding balances based on ageing categories and identify long-pending receivables and payables.","notes":""},{"code":"SID-A07-S01-03","text":"Select material outstanding balances and obtain supporting documents such as invoices, agreements, delivery proofs, and payment records for verification","notes":""},{"code":"SID-A07-S01-04","text":"Verify debit balances appearing in trade payables and credit balances appearing in trade receivables and obtain reasons for such balances.","notes":""},{"code":"SID-A07-S01-05","text":"Identify overdue receivables and payables and obtain explanations from management for significant outstanding balances.","notes":""}]}]},{"code":"SID-A08","name":"Loan and Interest Payable Verification","subtasks":[{"code":"SID-A08-S01","name":"Loan and Interest Payable Verification","steps":[{"code":"SID-A08-S01-01","text":"Obtain the details of all loans outstanding as per the books of accounts and verify the loan agreements, sanction letters, and terms & conditions with lenders.","notes":""},{"code":"SID-A08-S01-02","text":"Verify the principal amount received, repayments made, and outstanding loan balances as per bank statements and loan records in the Books","notes":""},{"code":"SID-A08-S01-03","text":"Verify interest payable calculations with reference to loan agreements, applicable interest rates, and repayment terms.","notes":""},{"code":"SID-A08-S01-04","text":"Ensure accrued interest payable at the reporting date is correctly accounted for in the financial statements.","notes":""},{"code":"SID-A08-S01-05","text":"Ensure accrued interest payable at the reporting date is correctly accounted for in the financial statements.","notes":""}]}]},{"code":"SID-A09","name":"Insurance Premium","subtasks":[{"code":"SID-A09-S01","name":"Insurance Premium","steps":[{"code":"SID-A09-S01-01","text":"Obtain the details of all insurance policies maintained by the Company and verify policy documents, coverage details, validity period, and insured assets/persons.","notes":""},{"code":"SID-A09-S01-02","text":"Verify insurance premium payments recorded in the books with policy documents, premium invoices, payment vouchers, and bank statements.","notes":""},{"code":"SID-A09-S01-03","text":"Verify that insurance premiums are recorded under the correct expense head and accounted for in the appropriate accounting period.","notes":""},{"code":"SID-A09-S01-04","text":"Verify renewal of insurance policies before expiry and ensure continuous coverage of assets and operations.","notes":""},{"code":"SID-A09-S01-05","text":"Identify expired policies, inadequate coverage, or significant deviations and report the same to management.","notes":""}]}]},{"code":"SID-A10","name":"Machine Handling Notes","subtasks":[{"code":"SID-A10-S01","name":"Machine Handling Notes","steps":[{"code":"SID-A10-S01-01","text":"Obtain the details of machines maintained by the Company and verify the machine register, asset details, location, and identification numbers.","notes":""},{"code":"SID-A10-S01-02","text":"Check whether regular maintenance schedules, servicing records, and breakdown are reported in the notes with approval sign.","notes":""},{"code":"SID-A10-S01-03","text":"Verify that trained and authorized personnel are assigned for operating machines","notes":""},{"code":"SID-A10-S01-04","text":"Inspect the physical condition of machines and identify idle, obsolete, or damaged equipment.","notes":""}]}]}]},{"key":"IA-GOP","name":"Internal Audit — N. Gopaldas Group (GOP)","scope":{"type":"client","value":"GOP","legacy_code":"GOP"},"areas":[{"code":"GOP-A01","name":"Sales Verification","subtasks":[{"code":"GOP-A01-S01","name":"1) Branchwise Sales Verification","steps":[{"code":"GOP-A01-S01-01","text":"Obtain the branch-wise Software sales report from the management in Excel format. Coordinate with Mr. Srinivas (HR), who is responsible for the software, to obtain the report.","notes":"Note: Details for the Mumbai and Hyderabad branches will be received at the Chennai office. For all remaining branches, the details must be verified through a physical visit."},{"code":"GOP-A01-S01-02","text":"Extract the Sales Report from Tally in Columnar format","notes":""},{"code":"GOP-A01-S01-03","text":"Obtain Physical Record of Invoices Maintained by the Store Managers","notes":""},{"code":"GOP-A01-S01-04","text":"Cross-verify whether the sales recorded in the accounts are accurate by comparing them with the physical invoices and the software-generated sales report.","notes":""}]},{"code":"GOP-A01-S02","name":"2) Metal wise Sales Verification","steps":[{"code":"GOP-A01-S02-01","text":"Using the provided report, classify the items into the appropriate metal categories based on the tag type, such as Gold (24KT, 22KT, 18KT, and 14KT), Diamond, Silver, Platinum, Stones, and Others and Find the weight of Individual metals","notes":""},{"code":"GOP-A01-S02-02","text":"Classify the items in the Tally report into the same categories on a branch-wise basis to ensure consistency with the provided report.","notes":""},{"code":"GOP-A01-S02-03","text":"Vouch the branch-wise classification by verifying that the item weights in the provided report and the Tally report are accurate and match for each category.","notes":""}]},{"code":"GOP-A01-S03","name":"3) Ornament Wise Sales Verification","steps":[{"code":"GOP-A01-S03-01","text":"Using the provided report, classify the Ornament sales in branch wise and record the details of highly sold items for the period","notes":""},{"code":"GOP-A01-S03-02","text":"Conduct a Oral Verification with the Store Manager related to Highly sold ornaments during the period","notes":""}]},{"code":"GOP-A01-S04","name":"4) Inter Company Sales Verification","steps":[{"code":"GOP-A01-S04-01","text":"This sales will Occure in the Branches Namely HYD, MUM and HO","notes":""},{"code":"GOP-A01-S04-02","text":"This sales need to Eliminate during the Net Sales computation as it form part of the Internal sales and all the Inter state sales must contain Tax Invoice","notes":""},{"code":"GOP-A01-S04-03","text":"Any unrealized profit is eliminated in consolidation if the goods remain unsold externally.","notes":""}]},{"code":"GOP-A01-S05","name":"5) Sales Return Analysis","steps":[{"code":"GOP-A01-S05-01","text":"Compare sales return transactions recorded in the software with the corresponding entries in Tally to ensure invoice numbers, dates, customer names, quantities, and amounts match without discrepancies.","notes":""},{"code":"GOP-A01-S05-02","text":"Check that each sales return entry is supported by valid documents such as credit notes, return authorization, and customer acknowledgments, and confirm that the entries are correctly posted in Tally.","notes":""}]}]},{"code":"GOP-A02","name":"Purchase Verification","subtasks":[{"code":"GOP-A02-S01","name":"1) Purchases From External Vendors Verification","steps":[{"code":"GOP-A02-S01-01","text":"Verify purchase invoices from external vendors with entries recorded in Tally, ensuring the supplier name, invoice number, date, quantity, purity (carat/fineness), gross/net weight, rate, and amount are correctly recorded.","notes":""},{"code":"GOP-A02-S01-02","text":"Verify that GST, making charges, wastage charges, and other applicable taxes/charges are correctly accounted for in Tally.","notes":""},{"code":"GOP-A02-S01-03","text":"Verify that payments to vendors are supported by bank/payment vouchers and correctly adjusted against the corresponding purchase invoices.","notes":""}]},{"code":"GOP-A02-S02","name":"2) Inter Company Purchase Verification","steps":[{"code":"GOP-A02-S02-01","text":"Cross-verify that the above intercompany sales are appropriately recorded as corresponding purchases in the respective branch's accounts in Tally.","notes":""}]},{"code":"GOP-A02-S03","name":"3) Metal wise Purchase Verification","steps":[{"code":"GOP-A02-S03-01","text":"Verify the metal-wise weight (Gold, Silver, Platinum, etc.) recorded in the purchase invoice with the corresponding entry in Tally.","notes":""},{"code":"GOP-A02-S03-02","text":"Cross-check gross weight, net weight, purity (carat/fineness), and standard weight as per the supplier invoice and assay report.","notes":""}]},{"code":"GOP-A02-S04","name":"4) Purchase Return Analysis","steps":[{"code":"GOP-A02-S04-01","text":"Verify that all purchase return entries in Tally are supported by valid debit notes, supplier acknowledgements, and purchase return vouchers.","notes":""},{"code":"GOP-A02-S04-02","text":"Cross-check the returned quantity, weight, purity, rate, and amount with the original purchase invoice and ensure the supplier ledger and inventory are correctly updated in Tally.","notes":""}]},{"code":"GOP-A02-S05","name":"5) Old Gold Purchase from Customers","steps":[{"code":"GOP-A02-S05-01","text":"Verify that old gold purchase transactions are supported by customer purchase forms/KYC documents, weight and purity test reports, and are accurately recorded in Tally.","notes":""},{"code":"GOP-A02-S05-02","text":"Cross-check the weight, purity, rate, deduction (if any), and purchase amount with the valuation sheet, and ensure the corresponding inventory and payment entries are correctly posted in Tally.","notes":""}]}]},{"code":"GOP-A03","name":"Expenses Vouching","subtasks":[{"code":"GOP-A03-S01","name":"Expenses Vouching","steps":[{"code":"GOP-A03-S01-01","text":"Verify that allexpenses are supported by original invoices, bills, and payment vouchers.","notes":""},{"code":"GOP-A03-S01-02","text":"Ensure expenses are properly approved by the authorized personnel.","notes":""},{"code":"GOP-A03-S01-03","text":"Ensure expenses are accuratley related to activities relating to Admin and Selling overheads","notes":""},{"code":"GOP-A03-S01-04","text":"Check supporting documents for freight, carriage inward, making charges, hallmarking charges, refining charges, and job work charges","notes":""},{"code":"GOP-A03-S01-05","text":"Review recurring expenses such as rent, salaries, electricity, telephone, insurance, repairs, and office maintenance for consistency.","notes":""},{"code":"GOP-A03-S01-06","text":"Confirm GST input credit is correctly accounted for wherever applicable.","notes":""},{"code":"GOP-A03-S01-07","text":"Verify that duplicate or unauthorized expense entries are not recorded.","notes":""},{"code":"GOP-A03-S01-08","text":"Investigate any unusual, high-value, or unsupported expense entries and obtain appropriate supporting documentation.","notes":""}]}]},{"code":"GOP-A04","name":"Statutory Compliance Verification","subtasks":[{"code":"GOP-A04-S01","name":"1. TDS (Tax Deducted at Source)","steps":[{"code":"GOP-A04-S01-01","text":"Verify that TDS has been deducted at the applicable rates on eligible payments and correctly recorded in Tally.","notes":"For More Info: https://taxguru.in/income-tax/income-tax-act-2025-tds-rates-thresholds-compliance-ty-2026-27.html"},{"code":"GOP-A04-S01-02","text":"Cross-check TDS deductions with challans, TDS returns, and ensure timely deposit with the government.","notes":""},{"code":"GOP-A04-S01-03","text":"Check Interest Calculation if any late payement in TDS","notes":""}]},{"code":"GOP-A04-S02","name":"2. PF (Provident Fund)","steps":[{"code":"GOP-A04-S02-01","text":"Check that contributions are generally calculated at 12% of Basic wages + Dearness Allowance","notes":"For More Info: https://www.epfindia.gov.in/site_docs/PDFs/MiscPDFs/Employer_Information_Booklet.pdf"},{"code":"GOP-A04-S02-02","text":"Verify the employee master data (joining date, basic wages, employee category, and UAN details).","notes":""},{"code":"GOP-A04-S02-03","text":"Verify that the employer’s contribution is appropriately allocated between EPF, EPS, and EDLI schemes as applicable.","notes":""},{"code":"GOP-A04-S02-04","text":"Verify monthly filing of PF Electronic Challan-cum-Return (ECR) through the EPFO portal.","notes":""},{"code":"GOP-A04-S02-05","text":"Verify PF payable and expense ledgers in Tally for correct accounting treatment.","notes":""},{"code":"GOP-A04-S02-06","text":"EPFO provisions, the statutory wage ceiling for PF contribution is ₹15,000 per month","notes":""},{"code":"GOP-A04-S02-07","text":"To pay contribution on higher wages, a joint request from both employer and employee is required [Para 26(6) of EPF Scheme]. In such case employer has to pay Administrative charges in A/c.No.2 on the higher wages. (wages above Rs.15,000/-).","notes":""}]},{"code":"GOP-A04-S03","name":"3. Employees’ State Insurance Corporation","steps":[{"code":"GOP-A04-S03-01","text":"Verify coverage based on the applicable wage ceiling of ₹21,000 per month (₹25,000 per month for employees with disabilities).","notes":"For More Info: https://esic.gov.in/attachments/publicationfile/6f673bcd3d6110170f790d2909767b4f.pdf?utm"},{"code":"GOP-A04-S03-02","text":"Employee Contribution: Verify that employee contribution is calculated at 0.75% of wages.","notes":""},{"code":"GOP-A04-S03-03","text":"Employer Contribution: Verify that employer contribution is calculated at 3.25% of wages.","notes":""},{"code":"GOP-A04-S03-04","text":"Reconcile ESIC deductions in the salary register with the ESIC payable ledger in Tally.","notes":""},{"code":"GOP-A04-S03-05","text":"Check ESIC challans and bank payment proofs for timely remittance","notes":""},{"code":"GOP-A04-S03-06","text":"Check that employer contribution is not deducted from employee salary.","notes":""}]},{"code":"GOP-A04-S04","name":"4.GST Compliance Verification","steps":[{"code":"GOP-A04-S04-01","text":"Verify sales invoices recorded in Tally with GST sales register and ensure invoice number, date, customer GSTIN, taxable value, and GST rate are correctly captured.","notes":""},{"code":"GOP-A04-S04-02","text":"Reconcile sales turnover as per Tally with turnover reported in GSTR-1 and tax liability discharged through GSTR-3B.","notes":""},{"code":"GOP-A04-S04-03","text":"Reconcile purchase register with GSTR-2B to ensure eligible Input Tax Credit is claimed only for valid invoices.","notes":""},{"code":"GOP-A04-S04-04","text":"Check whether blocked credits under GST provisions are excluded from ITC claims.","notes":""},{"code":"GOP-A04-S04-05","text":"Verify timely filing of: GSTR-1 (Outward supply details) GSTR-3B (Summary return and tax payment)","notes":""},{"code":"GOP-A04-S04-06","text":"Perform reconciliation between: 1.Sales Register vs GSTR-1 2.GST Liability vs GSTR-3B 3.Purchase Register vs GSTR-2B 4.ITC claimed vs eligible ITC","notes":""}]}]},{"code":"GOP-A05","name":"Cash and Bank Balance verification","subtasks":[{"code":"GOP-A05-S01","name":"1. Cash Balance verification","steps":[{"code":"GOP-A05-S01-01","text":"Check the cash book and note the recorded cash balance as of the verification date.","notes":""},{"code":"GOP-A05-S01-02","text":"Count all cash available, including: Notes (by denomination) Coins Petty cash balance (if applicable)","notes":""},{"code":"GOP-A05-S01-03","text":"Match the physically counted cash with the cash book balance.","notes":""}]},{"code":"GOP-A05-S02","name":"2. Bank Balance Verification","steps":[{"code":"GOP-A05-S02-01","text":"Obtain the latest bank statement from the bank.","notes":""},{"code":"GOP-A05-S02-02","text":"Compare the bank statement balance with the balance shown in the books of accounts.","notes":""},{"code":"GOP-A05-S02-03","text":"Prepare a summary report of unreconciled items with reasons and status of resolution.","notes":""}]}]},{"code":"GOP-A06","name":"Trade Receivables Ageing and Payable Ageing","subtasks":[{"code":"GOP-A06-S01","name":"1. Cash Balance verification","steps":[{"code":"GOP-A06-S01-01","text":"1. Extract Trade Receivable and Payable Ageing Report (Tally → Gateway of Tally → Display More Reports → Statements of Accounts → Outstanding → Receivables.)","notes":""},{"code":"GOP-A06-S01-02","text":"2. Review outstanding amounts based on ageing buckets: Current 0–30 days 31–60 days 61–90 days Above 90 days","notes":""},{"code":"GOP-A06-S01-03","text":"3. Perform Reconciliation Match: Customer-wise total with Tally ledger Supplier-wise total with Tally ledger","notes":""},{"code":"GOP-A06-S01-04","text":"4. Prepare Report Customer-wise outstanding report as on the verification date with remarks from Customer","notes":""}]}]},{"code":"GOP-A07","name":"Stock Valuation","subtasks":[{"code":"GOP-A07-S01","name":"Stock Valuation","steps":[{"code":"GOP-A07-S01-01","text":"Step 1: Obtain the opening stock records from the previous year’s audited financial statements and inventory records.","notes":""},{"code":"GOP-A07-S01-02","text":"Step 2: Extract all purchase transactions from Tally/ERP records for the valuation period.(Quantity purchased +Purchase value)","notes":""},{"code":"GOP-A07-S01-03","text":"Step 3: Weighted Average Base Rate = (Opening Stock Value + Purchase Value) ÷ (Opening Quantity + Purchased Quantity)","notes":""},{"code":"GOP-A07-S01-04","text":"Step 4: Identify and Allocate Eligible Inventory Costs as per AS 2","notes":""},{"code":"GOP-A07-S01-05","text":"Step 5: Eligible Expense per Unit = Total Eligible Expenses ÷ Total Value of Opening Stock + Purchase Value (Final Unit Cost = Weighted Average Material Rate + Eligible Expense per Unit)","notes":""},{"code":"GOP-A07-S01-06","text":"Step 6: Determine Closing Stock Quantity","notes":""},{"code":"GOP-A07-S01-07","text":"Step 7: Closing Stock Value = Closing Quantity × Final Unit Cost","notes":""}]}]},{"code":"GOP-A08","name":"N Gopaldas and Co – Additional Verification","subtasks":[{"code":"GOP-A08-S01","name":"N Gopaldas and Co – Additional Verification","steps":[{"code":"GOP-A08-S01-01","text":"Apart of the Above","notes":""},{"code":"GOP-A08-S01-02","text":"1) Verify all the Work Orders generated during the Period","notes":""},{"code":"GOP-A08-S01-03","text":"2) Cross Verify the Handstock Recorded in the Books as well as Physical Verification","notes":""},{"code":"GOP-A08-S01-04","text":"3) Verify the Export sale made during the period of verification as mentioned above","notes":""}]}]}]},{"key":"IA-MAH","name":"Internal Audit — Mahamaya (IA-MAH)","scope":{"type":"client","value":"IA-MAH","legacy_code":"MAH"},"areas":[{"code":"MAH-A01","name":"Sales Verification","subtasks":[{"code":"MAH-A01-S01","name":"1) Sales Vouching","steps":[{"code":"MAH-A01-S01-01","text":"Using random sampling on a materiality basis, select sales invoices and vouch them with supporting documents, dispatch records, and accounting entries in the books.","notes":""},{"code":"MAH-A01-S01-02","text":"Verify that sales are recorded in the correct period with accurate quantity, rate, value, and applicable taxes.","notes":""}]},{"code":"MAH-A01-S02","name":"2) Inter-Branch Sales Verification","steps":[{"code":"MAH-A01-S02-01","text":"Identify inter-branch (stock transfer) sales and verify that they are correctly recorded in both the transferring and receiving branch accounts.","notes":""},{"code":"MAH-A01-S02-02","text":"Ensure inter-branch sales are eliminated while arriving at the net sales, as they form part of internal transactions.","notes":""}]},{"code":"MAH-A01-S03","name":"3) Sales Register","steps":[{"code":"MAH-A01-S03-01","text":"Maintain a Sales Register to track sales branch-wise and reconcile it with the sales recorded in the books of accounts.","notes":""}]}]},{"code":"MAH-A02","name":"Purchase Verification","subtasks":[{"code":"MAH-A02-S01","name":"1) Purchase Vouching","steps":[{"code":"MAH-A02-S01-01","text":"Using random sampling on a materiality basis, vouch purchase invoices with purchase orders, goods receipt records, and entries recorded in the books.","notes":""},{"code":"MAH-A02-S01-02","text":"Verify supplier name, invoice number, date, quantity, rate, amount, and applicable GST are correctly recorded.","notes":""}]},{"code":"MAH-A02-S02","name":"2) Inter-Branch Purchase Verification","steps":[{"code":"MAH-A02-S02-01","text":"Cross-verify that inter-branch sales / stock transfers are appropriately recorded as corresponding purchases in the receiving branch accounts.","notes":""}]},{"code":"MAH-A02-S03","name":"3) Three-Way Matching (PO – GRN – Invoice)","steps":[{"code":"MAH-A02-S03-01","text":"Perform a three-way match between the Purchase Order (PO), Goods Receipt Note (GRN), and the supplier Invoice to confirm quantity, rate, and value agree across all three documents.","notes":""},{"code":"MAH-A02-S03-02","text":"Investigate and report any discrepancies identified during the three-way matching.","notes":""}]},{"code":"MAH-A02-S04","name":"4) Customs Duty Workings","steps":[{"code":"MAH-A02-S04-01","text":"Prepare customs duty workings for imported purchases and verify the duty computed against the Bill of Entry and payment challans.","notes":""},{"code":"MAH-A02-S04-02","text":"Ensure customs duty and related charges are correctly loaded to the landed cost of imported materials.","notes":""}]}]},{"code":"MAH-A03","name":"Expenses Verification","subtasks":[{"code":"MAH-A03-S01","name":"1) Expense Vouching","steps":[{"code":"MAH-A03-S01-01","text":"Vouch total direct and indirect expenses on a materiality basis with original invoices, bills, and payment vouchers.","notes":""},{"code":"MAH-A03-S01-02","text":"Ensure expenses are properly approved by authorised personnel and recorded under the correct expense head and period.","notes":""},{"code":"MAH-A03-S01-03","text":"Confirm GST input credit is correctly accounted for wherever applicable and investigate unusual or high-value entries.","notes":""}]},{"code":"MAH-A03-S02","name":"2) Fixed Asset Register","steps":[{"code":"MAH-A03-S02-01","text":"Prepare and maintain a Fixed Asset Register to track the purchase of assets, including description, location, purchase date, and cost.","notes":""},{"code":"MAH-A03-S02-02","text":"Ensure depreciation is correctly calculated and recorded as per the Company's accounting policies and applicable standards.","notes":""}]}]},{"code":"MAH-A04","name":"Statutory Compliance Verification","subtasks":[{"code":"MAH-A04-S01","name":"1. TDS (Tax Deducted at Source)","steps":[{"code":"MAH-A04-S01-01","text":"Verify that TDS has been deducted at the applicable rates on eligible payments and correctly recorded in Tally.","notes":""},{"code":"MAH-A04-S01-02","text":"Cross-check TDS deductions with challans, TDS returns, and ensure timely deposit with the government.","notes":""},{"code":"MAH-A04-S01-03","text":"Recalculate TDS payable and cross check with tally whether TDS has been deducted as per applicable rate","notes":""},{"code":"MAH-A04-S01-04","text":"Check Interest Calculation if any late payement in TDS","notes":""}]},{"code":"MAH-A04-S02","name":"2. PF (Provident Fund)","steps":[{"code":"MAH-A04-S02-01","text":"Check that contributions are generally calculated at 12% of Basic wages + Dearness Allowance","notes":""},{"code":"MAH-A04-S02-02","text":"Verify the employee master data (joining date, basic wages, employee category, and UAN details).","notes":""},{"code":"MAH-A04-S02-03","text":"Verify monthly filing of PF Electronic Challan-cum-Return (ECR).","notes":""},{"code":"MAH-A04-S02-04","text":"Verify PF payable and expense ledgers in Tally for correct accounting treatment.","notes":""},{"code":"MAH-A04-S02-05","text":"EPFO provisions, the statutory wage ceiling for PF contribution is ₹15,000 per month","notes":""}]},{"code":"MAH-A04-S03","name":"3. Employees' State Insurance Corporation","steps":[{"code":"MAH-A04-S03-01","text":"Reconcile ESIC deductions in the salary register with the ESIC payable ledger in Tally.","notes":""},{"code":"MAH-A04-S03-02","text":"Check ESIC challans and bank payment proofs for timely remittance","notes":""},{"code":"MAH-A04-S03-03","text":"Check that employer contribution is not deducted from employee salary.","notes":""}]},{"code":"MAH-A04-S04","name":"4. GST Compliance Verification","steps":[{"code":"MAH-A04-S04-01","text":"Verify sales invoices recorded in Tally with GST sales register and ensure invoice number, date, customer GSTIN, taxable value, and GST rate are correctly captured.","notes":""},{"code":"MAH-A04-S04-02","text":"Reconcile sales turnover as per Tally with turnover reported in GSTR-1 and tax liability discharged through GSTR-3B.","notes":""},{"code":"MAH-A04-S04-03","text":"Reconcile purchase register with GSTR-2B to ensure eligible Input Tax Credit is claimed only for valid invoices.","notes":""},{"code":"MAH-A04-S04-04","text":"Check whether blocked credits under GST provisions are excluded from ITC claims.","notes":""},{"code":"MAH-A04-S04-05","text":"Verify timely filing of: GSTR-1 (Outward supply details) GSTR-3B (Summary return and tax payment)","notes":""},{"code":"MAH-A04-S04-06","text":"Perform reconciliation between: 1.Sales Register vs GSTR-1 2.GST Liability vs GSTR-3B 3.Purchase Register vs GSTR-2B 4.ITC claimed vs eligible ITC","notes":""}]},{"code":"MAH-A04-S05","name":"5. IPO Fund Utilisation Verification","steps":[{"code":"MAH-A04-S05-01","text":"Verify the utilisation of IPO proceeds against the objects of the issue as stated in the prospectus / offer document.","notes":""},{"code":"MAH-A04-S05-02","text":"Reconcile the amounts utilised with bank statements and supporting documents, and verify the balance of unutilised funds.","notes":""},{"code":"MAH-A04-S05-03","text":"Ensure disclosures on IPO fund utilisation are made as per SEBI (LODR) Regulations and reported to the monitoring agency / board, where applicable.","notes":""}]}]},{"code":"MAH-A05","name":"Cash and Bank Balance verification","subtasks":[{"code":"MAH-A05-S01","name":"1. Cash Balance verification","steps":[{"code":"MAH-A05-S01-01","text":"Check the cash book and note the recorded cash balance as of the verification date.","notes":""},{"code":"MAH-A05-S01-02","text":"Match the physically counted cash with the cash book balance.","notes":""}]},{"code":"MAH-A05-S02","name":"2. Bank Balance Verification","steps":[{"code":"MAH-A05-S02-01","text":"Obtain the latest bank statement from the bank.","notes":""},{"code":"MAH-A05-S02-02","text":"Compare the bank statement balance with the balance shown in the books of accounts.","notes":""},{"code":"MAH-A05-S02-03","text":"Verify credit card statements and bank statements, and identify unreconciled items.","notes":""},{"code":"MAH-A05-S02-04","text":"Prepare a summary report of unreconciled items with reasons and status of resolution.","notes":""}]}]},{"code":"MAH-A06","name":"Stock Valuation","subtasks":[{"code":"MAH-A06-S01","name":"1) Landed Cost per Unit","steps":[{"code":"MAH-A06-S01-01","text":"Prepare a Purchase Register to arrive at the landed cost per unit, including customs duty, freight, and other directly attributable costs.","notes":""}]},{"code":"MAH-A06-S02","name":"2) Stock Categorisation","steps":[{"code":"MAH-A06-S02-01","text":"Categorise stock into Brand, Technical, Manufacturing, Packing Material, and Other Raw Material for accurate valuation and reporting.","notes":""}]},{"code":"MAH-A06-S03","name":"3) Stock Valuation Method","steps":[{"code":"MAH-A06-S03-01","text":"Use the Monthly Moving Average method to arrive at the closing stock balance.","notes":""}]},{"code":"MAH-A06-S04","name":"4) Physical vs Books Reconciliation","steps":[{"code":"MAH-A06-S04-01","text":"Prepare a Physical vs Books stock statement on a monthly basis and investigate and report any discrepancies.","notes":""}]}]},{"code":"MAH-A07","name":"MIS","subtasks":[{"code":"MAH-A07-S01","name":"MIS","steps":[{"code":"MAH-A07-S01-01","text":"Prepare the MIS (Monthly Information Statement) report to arrive at the Profit & Loss for the period.","notes":""},{"code":"MAH-A07-S01-02","text":"Update the key financial ratios for management performance review and decision making.","notes":""}]}]}]}];
